#include <iostream>
#include <fstream>
#include "quaternion_curve_sampler.h"
int main(int argc,char**argv){if(argc!=2)return 1;static_assert(sizeof(void*)==8);std::ifstream f(argv[1],std::ios::binary);if(!f)return 1;unsigned checks=0,mismatches=0;while(true){uint32_t mode;int32_t tick;std::array<float,4>expected;f.read(reinterpret_cast<char*>(&mode),4);if(f.gcount()==0&&f.eof())break;f.read(reinterpret_cast<char*>(&tick),4);f.read(reinterpret_cast<char*>(expected.data()),16);if(!f||mode>127)return 2;unsigned flags=mode/16;mode%=16;RecoveredQuaternionCurveSampler s;s.times={0,10000,30000,70000};s.values={{{0,0,0,1}},{{0,.70710677f,0,.70710677f}},{{0,0,0,-1}},{{.70710677f,0,0,.70710677f}}};s.kinds.assign(4,mode*257);s.info.defaultKind=mode*257;s.info.rightEdgeTime=80000;s.info.useEdgeInfo=(flags&1)!=0;s.info.leftActive=(flags&2)!=0;s.info.rightActive=(flags&4)!=0;s.info.disabledEdgeValue={-8,-10,-12};s.info.defaultEdgeZero={0,0,0,1};s.info.leftValue={0,0,0,1};s.info.rightValue={0,0,0,1};auto actual=s.sample(tick);if(std::memcmp(actual.data(),expected.data(),16)){++mismatches;if(mismatches<5)std::cout<<"mode="<<mode<<" tick="<<tick<<'\n';}++checks;}std::cout<<"native_quaternion_full_x64_checks="<<checks<<" mismatches="<<mismatches<<'\n';return checks==12928&&!mismatches?0:3;}
